         assert forall|i: int| #![auto] 0 <= i < sb@.chunks.len()
             implies sb@.chunks[i].0 + sb@.chunks[i].1 <= usize::MAX as int
         by {
             assert(sb@.chunks[i].0 == sb.chunks@[i].offset as int);
