             implies sb@.chunks[i].0 + sb@.chunks[i].1 <= sb@.chunks[j].0
         by {
             assert(sb@.chunks[i].0 == sb.chunks@[i].offset as int);
             assert(sb@.chunks[i].1 == sb.chunks@[i].bitmap@.num_bits);
             assert(sb@.chunks[j].0 == sb.chunks@[j].offset as int);
         }

