         lemma_lifted_set_bits_subset(sb.chunks@, 0);
         assert forall|g: int| #![auto] sb@.set_bits.contains(g)
             implies sb@.is_covered(g)
         by {
             let k = choose|k: int|
                 #![trigger sb.chunks@[k]]
                 0 <= k < sb.chunks@.len()
